local function notify(title, msg)
	pcall(function()
		game:GetService("StarterGui"):SetCore("SendNotification", {Title = title, Text = tostring(msg):sub(1, 180), Duration = 10})
	end)
end

local function b64decode(s)
	s = s:gsub("[^A-Za-z0-9%+/]", "")
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local map = {}
	for i = 1, 64 do
		map[chars:byte(i)] = i - 1
	end
	local out, n = {}, #s
	for i = 1, n, 4 do
		local c1, c2, c3, c4 = s:byte(i, i + 3)
		local v1, v2 = map[c1], map[c2]
		local v3 = c3 and map[c3]
		local v4 = c4 and map[c4]
		local num = v1 * 262144 + v2 * 4096 + (v3 or 0) * 64 + (v4 or 0)
		local b1 = math.floor(num / 65536)
		local b2 = math.floor(num / 256) % 256
		local b3 = num % 256
		if v4 then
			out[#out + 1] = string.char(b1, b2, b3)
		elseif v3 then
			out[#out + 1] = string.char(b1, b2)
		else
			out[#out + 1] = string.char(b1)
		end
	end
	return table.concat(out)
end

-- [v1.31] SHA-256 (Luau: ใช้ bit32) ตรวจความสมบูรณ์ของโค้ดหลังถอดรหัส base64
local function sha256Hex(msg)
	local b32 = bit32
	if type(b32) ~= "table" then return nil, "no bit32" end
	local band, bxor, bnot, rshift, lshift, bor, rrotate = b32.band, b32.bxor, b32.bnot, b32.rshift, b32.lshift, b32.bor, b32.rrotate
	local K = {
		0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
		0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
		0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
		0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
		0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
		0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
		0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
		0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
	}
	local H = { 0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19 }
	local len = #msg
	local bitLen = len * 8
	local hi = math.floor(bitLen / 4294967296)
	local lo = bitLen % 4294967296
	local pad = (55 - len) % 64
	msg = msg .. "\128" .. string.rep("\0", pad)
		.. string.char(band(rshift(hi, 24), 255), band(rshift(hi, 16), 255), band(rshift(hi, 8), 255), band(hi, 255),
			band(rshift(lo, 24), 255), band(rshift(lo, 16), 255), band(rshift(lo, 8), 255), band(lo, 255))
	local w = {}
	local blocks = #msg / 64
	for blk = 0, blocks - 1 do
		local base = blk * 64
		for j = 0, 15 do
			local b1, b2, b3, b4 = string.byte(msg, base + j * 4 + 1, base + j * 4 + 4)
			w[j + 1] = b1 * 16777216 + b2 * 65536 + b3 * 256 + b4
		end
		for j = 17, 64 do
			local x, y = w[j - 15], w[j - 2]
			local s0 = bxor(rrotate(x, 7), rrotate(x, 18), rshift(x, 3))
			local s1 = bxor(rrotate(y, 17), rrotate(y, 19), rshift(y, 10))
			w[j] = (w[j - 16] + s0 + w[j - 7] + s1) % 4294967296
		end
		local a, b, c, d, e, f, g, h = H[1], H[2], H[3], H[4], H[5], H[6], H[7], H[8]
		for j = 1, 64 do
			local S1 = bxor(rrotate(e, 6), rrotate(e, 11), rrotate(e, 25))
			local ch = bxor(band(e, f), band(bnot(e), g))
			local t1 = (h + S1 + ch + K[j] + w[j]) % 4294967296
			local S0 = bxor(rrotate(a, 2), rrotate(a, 13), rrotate(a, 22))
			local maj = bxor(band(a, b), band(a, c), band(b, c))
			local t2 = (S0 + maj) % 4294967296
			h, g, f, e, d, c, b, a = g, f, e, (d + t1) % 4294967296, c, b, a, (t1 + t2) % 4294967296
		end
		H[1] = (H[1] + a) % 4294967296; H[2] = (H[2] + b) % 4294967296
		H[3] = (H[3] + c) % 4294967296; H[4] = (H[4] + d) % 4294967296
		H[5] = (H[5] + e) % 4294967296; H[6] = (H[6] + f) % 4294967296
		H[7] = (H[7] + g) % 4294967296; H[8] = (H[8] + h) % 4294967296
		if blk % 512 == 511 and task and task.wait then task.wait() end -- ไม่ให้เกมค้างระหว่างคำนวณ
	end
	local out = {}
	for i = 1, 8 do out[i] = string.format("%08x", H[i]) end
	return table.concat(out)
end

local okDecode, srcOrErr = pcall(b64decode, PAYLOAD)
if not okDecode then
	return notify("BALL KUN: decode failed", srcOrErr)
end
local src = srcOrErr
if #src ~= EXPECTED_BYTES then
	return notify("BALL KUN: data corrupted", "got " .. #src .. " bytes, expected " .. EXPECTED_BYTES .. " (paste again, whole file)")
end

-- [v1.31] ตรวจ SHA-256 (ป้องกันไฟล์เสียแบบขนาดเท่าเดิมแต่เนื้อหาเพี้ยน) ถ้า Executor ไม่มี bit32 จะข้ามพร้อมแจ้งเตือน
do
	local okH, got = pcall(sha256Hex, src)
	if okH and got then
		if got ~= EXPECTED_SHA256 then
			return notify("BALL KUN: data corrupted (SHA-256)", "hash ไม่ตรง: ไฟล์เสียหรือถูกแก้ ให้คัดลอกใหม่ทั้งไฟล์")
		end
	else
		warn("[BALL KUN] ข้ามการตรวจ SHA-256: " .. tostring(okH and "ไม่มี bit32" or got))
	end
end

-- เก็บสำเนาในเครื่องไว้ให้ AutoExecOnHop ใช้ (ไม่ดึงจากเน็ต)
pcall(function() writefile("BallKun_v1_38_src.lua", src) end)

local fn, err = loadstring(src)
if not fn then
	return notify("BALL KUN: compile failed", err)
end
pcall(function() getgenv().__BALLKUN_RERUN = fn end) -- ให้ปุ่ม RETRY ของหน้า Loading เรียกกลับมา
